	private void applyAnnotationToMethodDeclFor(JavacNode typeNode, JCMethodDecl mth, String annType, boolean typeUse) {
		if (annType == null || mth == null) return;
		this.annotationScanNode = typeNode;
		JavacTreeMaker maker = typeNode.getTreeMaker();
		JCAnnotation m = maker.Annotation(genTypeRef(typeNode, annType), List.<JCExpression>nil());
		if (typeUse) {
			JCExpression resType = mth.restype;
			if (resType instanceof JCTypeApply) {
				JCTypeApply ta = (JCTypeApply) resType;
				if (ta.clazz instanceof JCFieldAccess) {
					mth.restype = maker.TypeApply(maker.AnnotatedType(List.of(m), ta.clazz), ta.arguments);
					return;
				}
				resType = ta.clazz;
			}
			if (resType instanceof JCFieldAccess || resType instanceof JCArrayTypeTree) {
				mth.restype = maker.AnnotatedType(List.of(m), resType);
				return;
			}
			if (JavacHandlerUtil.JCAnnotatedTypeReflect.is(resType)) {
				List<JCAnnotation> annotations = JavacHandlerUtil.JCAnnotatedTypeReflect.getAnnotations(resType);
				JavacHandlerUtil.JCAnnotatedTypeReflect.setAnnotations(resType, annotations.prepend(m));
				return;
			}
			if (resType instanceof JCPrimitiveTypeTree || resType instanceof JCIdent) {
				mth.mods.annotations = mth.mods.annotations == null ? List.of(m) : mth.mods.annotations.prepend(m);
			}
		} else {
			mth.mods.annotations = mth.mods.annotations == null ? List.of(m) : mth.mods.annotations.prepend(m);
		}
	}

	private void applyAnnotationToVarDeclFor(JavacNode typeNode, JCVariableDecl arg, String annType, boolean typeUse) {
		if (annType == null || arg == null) return;
		this.annotationScanNode = typeNode;
		JavacTreeMaker maker = typeNode.getTreeMaker();
		JCAnnotation m = maker.Annotation(genTypeRef(typeNode, annType), List.<JCExpression>nil());
		if (typeUse) {
			JCExpression varType = arg.vartype;
			JCTypeApply ta = null;
			if (varType instanceof JCTypeApply) {
				ta = (JCTypeApply) varType;
				varType = ta.clazz;
			}
			if (varType instanceof JCFieldAccess || varType instanceof JCArrayTypeTree) {
				varType = maker.AnnotatedType(List.of(m), varType);
				if (ta != null) ta.clazz = varType;
				else arg.vartype = varType;
				return;
			}
			if (JavacHandlerUtil.JCAnnotatedTypeReflect.is(varType)) {
				List<JCAnnotation> annotations = JavacHandlerUtil.JCAnnotatedTypeReflect.getAnnotations(varType);
				JavacHandlerUtil.JCAnnotatedTypeReflect.setAnnotations(varType, annotations.prepend(m));
				return;
			}
			if (varType instanceof JCPrimitiveTypeTree || varType instanceof JCIdent) {
				arg.mods.annotations = arg.mods.annotations == null ? List.of(m) : arg.mods.annotations.prepend(m);
			}
		} else {
			arg.mods.annotations = arg.mods.annotations == null ? List.of(m) : arg.mods.annotations.prepend(m);
		}
	}

	private void captureConstructorContext(JavacNode typeNode, AccessLevel level, List<JavacNode> fields, boolean forceDefaults, String staticName, List<JCAnnotation> onConstructor, HandleConstructor.SkipIfConstructorExists skipIfConstructorExists) {

		this.constructorTypeNode = typeNode;
		this.constructorAccessLevel = level;
		this.constructorFields = fields;
		this.constructorForceDefaults = forceDefaults;
		this.constructorStaticName = staticName;
		this.constructorOnConstructor = onConstructor;
		this.constructorSkipMode = skipIfConstructorExists;
	}

	public List<JavacNode> findRequiredFieldsFor(JavacNode typeNode) {

		this.constructorTypeNode = typeNode;
		return findFieldsFor(typeNode, true);
	}

	public List<JavacNode> findFinalFieldsFor(JavacNode typeNode) {

		this.constructorTypeNode = typeNode;
		return findFieldsFor(typeNode, false);
	}

	public List<JavacNode> findFieldsFor(JavacNode typeNode, boolean nullMarked) {

		this.constructorTypeNode = typeNode;
		ListBuffer<JavacNode> fields = new ListBuffer<JavacNode>();
		if (typeNode == null) return fields.toList();
		for (JavacNode child : typeNode.down()) {
			if (child.getKind() != Kind.FIELD) continue;
			if (!isConstructorCandidateField(child, nullMarked)) continue;
			fields.append(child);
		}
		this.constructorFields = fields.toList();
		return this.constructorFields;
	}

	private boolean isConstructorCandidateField(JavacNode child, boolean nullMarked) {
		this.constructorTypeNode = child == null ? this.constructorTypeNode : child.up();

		JCVariableDecl fieldDecl = (JCVariableDecl) child.get();
		if (fieldDecl.name.toString().startsWith("$")) return false;
		long fieldFlags = fieldDecl.mods.flags;
		if ((fieldFlags & Flags.STATIC) != 0) return false;
		boolean isFinal = (fieldFlags & Flags.FINAL) != 0;
		boolean isNonNull = nullMarked && hasNonNullAnnotationsOn(child);
		return (isFinal || isNonNull) && fieldDecl.init == null;
	}

	public List<JavacNode> findAllFieldsFor(JavacNode typeNode) {
		this.constructorTypeNode = typeNode;

		return findAllFieldsFor(typeNode, false);
	}

	public List<JavacNode> findAllFieldsFor(JavacNode typeNode, boolean evenFinalInitialized) {

		this.constructorTypeNode = typeNode;
		ListBuffer<JavacNode> fields = new ListBuffer<JavacNode>();
		if (typeNode == null) return fields.toList();
		for (JavacNode child : typeNode.down()) {
			if (child.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) child.get();
			if (fieldDecl.name.toString().startsWith("$")) continue;
			long fieldFlags = fieldDecl.mods.flags;
			if ((fieldFlags & Flags.STATIC) != 0) continue;
			boolean isFinal = (fieldFlags & Flags.FINAL) != 0;
			if (evenFinalInitialized || !isFinal || fieldDecl.init == null) fields.append(child);
		}
		this.constructorFields = fields.toList();
		return this.constructorFields;
	}

	public void generateExtraNoArgsConstructorFor(JavacNode typeNode, JavacNode source) {
		this.constructorTypeNode = typeNode;

		captureConstructorContext(typeNode, AccessLevel.PRIVATE, List.<JavacNode>nil(), true, null, List.<JCAnnotation>nil(), HandleConstructor.SkipIfConstructorExists.NO);
		if (!isDirectDescendantOfObject(typeNode)) return;
		Boolean v = typeNode.getAst().readConfiguration(ConfigurationKeys.NO_ARGS_CONSTRUCTOR_EXTRA_PRIVATE);
		if (v == null || !v) return;
		generateConstructorInternal(typeNode, AccessLevel.PRIVATE, List.<JCAnnotation>nil(), List.<JavacNode>nil(), true, null, HandleConstructor.SkipIfConstructorExists.NO, source, true);
	}

	public void generateRequiredArgsConstructorFor(JavacNode typeNode, AccessLevel level, String staticName, HandleConstructor.SkipIfConstructorExists skipIfConstructorExists, JavacNode source) {
		this.constructorTypeNode = typeNode;

		List<JavacNode> fields = findRequiredFieldsFor(typeNode);
		captureConstructorContext(typeNode, level, fields, false, staticName, List.<JCAnnotation>nil(), skipIfConstructorExists);
		generateConstructorFor(typeNode, level, List.<JCAnnotation>nil(), fields, false, staticName, skipIfConstructorExists, source);
	}

	public void generateAllArgsConstructorFor(JavacNode typeNode, AccessLevel level, String staticName, HandleConstructor.SkipIfConstructorExists skipIfConstructorExists, JavacNode source) {
		this.constructorTypeNode = typeNode;

		List<JavacNode> fields = findAllFieldsFor(typeNode);
		captureConstructorContext(typeNode, level, fields, false, staticName, List.<JCAnnotation>nil(), skipIfConstructorExists);
		generateConstructorFor(typeNode, level, List.<JCAnnotation>nil(), fields, false, staticName, skipIfConstructorExists, source);
	}

	public void generateConstructorFor(JavacNode typeNode, AccessLevel level, List<JCAnnotation> onConstructor, List<JavacNode> fields, boolean allToDefault, String staticName, HandleConstructor.SkipIfConstructorExists skipIfConstructorExists, JavacNode source) {
		this.constructorTypeNode = typeNode;

		captureConstructorContext(typeNode, level, fields, allToDefault, staticName, onConstructor, skipIfConstructorExists);
		generateConstructorInternal(typeNode, level, onConstructor, fields, allToDefault, staticName, skipIfConstructorExists, source, false);
	}

	private void generateConstructorInternal(JavacNode typeNode, AccessLevel level, List<JCAnnotation> onConstructor, List<JavacNode> fields, boolean allToDefault, String staticName, HandleConstructor.SkipIfConstructorExists skipIfConstructorExists, JavacNode source, boolean noArgs) {
		this.constructorTypeNode = typeNode;

		boolean staticConstrRequired = staticName != null && !staticName.equals("");
		if (shouldSkipConstructorGeneration(typeNode, skipIfConstructorExists, staticConstrRequired, source)) return;
		if (noArgs && noArgsConstructorExistsFor(typeNode)) return;
		if (!(skipIfConstructorExists != HandleConstructor.SkipIfConstructorExists.NO && constructorExists(typeNode) != MemberExistsResult.NOT_EXISTS)) {
			JCMethodDecl constr = createConstructorFor(staticConstrRequired ? AccessLevel.PRIVATE : level, onConstructor, typeNode, fields, allToDefault, source);
			injectMethod(typeNode, constr);
		}
		generateStaticConstructorFor(staticConstrRequired, typeNode, staticName, level, allToDefault, fields, source);
	}

	private boolean shouldSkipConstructorGeneration(JavacNode typeNode, HandleConstructor.SkipIfConstructorExists skipIfConstructorExists, boolean staticConstrRequired, JavacNode source) {
		this.constructorTypeNode = typeNode;

		if (skipIfConstructorExists == HandleConstructor.SkipIfConstructorExists.NO) return false;
		for (JavacNode child : typeNode.down()) {
			if (child.getKind() != Kind.ANNOTATION) continue;
			boolean skipGeneration = annotationTypeMatches(NoArgsConstructor.class, child) ||
				annotationTypeMatches(AllArgsConstructor.class, child) ||
				annotationTypeMatches(RequiredArgsConstructor.class, child);
			if (!skipGeneration && skipIfConstructorExists == HandleConstructor.SkipIfConstructorExists.YES) {
				skipGeneration = annotationTypeMatches(Builder.class, child);
			}
			if (skipGeneration) {
				if (staticConstrRequired) {
					source.addWarning("Ignoring static constructor name: explicit @XxxArgsConstructor annotation present; its `staticName` parameter will be used.");
				}
				return true;
			}
		}
		return false;
	}

	private void generateStaticConstructorFor(boolean staticConstrRequired, JavacNode typeNode, String staticName, AccessLevel level, boolean allToDefault, List<JavacNode> fields, JavacNode source) {

		this.constructorTypeNode = typeNode;
		this.constructorStaticName = staticName;
		if (staticConstrRequired) {
			JCMethodDecl staticConstr = createStaticConstructorFor(staticName, level, typeNode, allToDefault ? List.<JavacNode>nil() : fields, source);
			injectMethod(typeNode, staticConstr);
		}
	}

	private boolean noArgsConstructorExistsFor(JavacNode node) {

		this.constructorTypeNode = node;
		node = upToTypeNode(node);
		if (node != null && node.get() instanceof JCClassDecl) {
			for (JCTree def : ((JCClassDecl) node.get()).defs) {
				if (def instanceof JCMethodDecl) {
					JCMethodDecl md = (JCMethodDecl) def;
					if (md.name.contentEquals("<init>") && md.params.size() == 0) return true;
				}
			}
		}
		for (JavacNode child : node.down()) {
			if (annotationTypeMatches(NoArgsConstructor.class, child)) return true;
			if (annotationTypeMatches(RequiredArgsConstructor.class, child) && findRequiredFieldsFor(node).isEmpty()) return true;
			if (annotationTypeMatches(AllArgsConstructor.class, child) && findAllFieldsFor(node).isEmpty()) return true;
		}
		return false;
	}

	public void addConstructorPropertiesFor(JCModifiers mods, JavacNode node, List<JavacNode> fields) {

		this.constructorTypeNode = node;
		this.constructorFields = fields;
		if (fields == null || fields.isEmpty()) return;
		JavacTreeMaker maker = node.getTreeMaker();
		JCExpression constructorPropertiesType = chainDots(node, "java", "beans", "ConstructorProperties");
		ListBuffer<JCExpression> fieldNames = new ListBuffer<JCExpression>();
		for (JavacNode field : fields) {
			Name fieldName = removePrefixFromField(field);
			fieldNames.append(maker.Literal(fieldName.toString()));
		}
		JCExpression fieldNamesArray = maker.NewArray(null, List.<JCExpression>nil(), fieldNames.toList());
		JCAnnotation annotation = maker.Annotation(constructorPropertiesType, List.of(fieldNamesArray));
		mods.annotations = mods.annotations.append(annotation);
	}

	@SuppressWarnings("deprecation") public JCMethodDecl createConstructorFor(AccessLevel level, List<JCAnnotation> onConstructor, JavacNode typeNode, List<JavacNode> fieldsToParam, boolean forceDefaults, JavacNode source) {
		this.constructorTypeNode = typeNode;

		captureConstructorContext(typeNode, level, fieldsToParam, forceDefaults, this.constructorStaticName, onConstructor, this.constructorSkipMode);
		JavacTreeMaker maker = typeNode.getTreeMaker();
		boolean isEnum = (((JCClassDecl) typeNode.get()).mods.flags & Flags.ENUM) != 0;
		if (isEnum) level = AccessLevel.PRIVATE;
		boolean addConstructorProperties;
		List<JavacNode> fieldsToDefault = fieldsNeedingBuilderDefaultsFor(typeNode, fieldsToParam);
		List<JavacNode> fieldsToExplicit = forceDefaults ? fieldsNeedingExplicitDefaultsFor(typeNode, fieldsToParam) : List.<JavacNode>nil();
		if (fieldsToParam.isEmpty()) {
			addConstructorProperties = false;
		} else {
			Boolean v = typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_ADD_CONSTRUCTOR_PROPERTIES);
			addConstructorProperties = v != null ? v.booleanValue() :
				Boolean.FALSE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_SUPPRESS_CONSTRUCTOR_PROPERTIES));
		}
		ListBuffer<JCStatement> nullChecks = new ListBuffer<JCStatement>();
		ListBuffer<JCStatement> assigns = new ListBuffer<JCStatement>();
		ListBuffer<JCVariableDecl> params = new ListBuffer<JCVariableDecl>();
		for (JavacNode fieldNode : fieldsToParam) {
			JCVariableDecl field = (JCVariableDecl) fieldNode.get();
			Name fieldName = removePrefixFromField(fieldNode);
			Name rawName = field.name;
			List<JCAnnotation> copyableAnnotations = findCopyableAnnotationsFor(fieldNode);
			long flags = JavacHandlerUtil.addFinalIfNeeded(Flags.PARAMETER, typeNode.getContext());
			JCExpression pType = cloneType(fieldNode.getTreeMaker(), field.vartype, source);
			JCVariableDecl param = maker.VarDef(maker.Modifiers(flags, copyableAnnotations), fieldName, pType, null);
			params.append(param);
			if (hasNonNullAnnotationsOn(fieldNode)) {
				JCStatement nullCheck = generateNullCheckForDeclaration(maker, param, source);
				if (nullCheck != null) nullChecks.append(nullCheck);
			}
			JCFieldAccess thisX = maker.Select(maker.Ident(fieldNode.toName("this")), rawName);
			JCExpression assign = maker.Assign(thisX, maker.Ident(fieldName));
			assigns.append(maker.Exec(assign));
		}
		for (JavacNode fieldNode : fieldsToExplicit) {
			JCVariableDecl field = (JCVariableDecl) fieldNode.get();
			Name rawName = field.name;
			JCFieldAccess thisX = maker.Select(maker.Ident(fieldNode.toName("this")), rawName);
			JCExpression assign = maker.Assign(thisX, defaultExpressionFor(maker, field.vartype));
			assigns.append(maker.Exec(assign));
		}
		for (JavacNode fieldNode : fieldsToDefault) {
			JCVariableDecl field = (JCVariableDecl) fieldNode.get();
			Name rawName = field.name;
			Name fieldName = removePrefixFromField(fieldNode);
			Name nameOfDefaultProvider = typeNode.toName("$default$" + fieldName);
			JCFieldAccess thisX = maker.Select(maker.Ident(fieldNode.toName("this")), rawName);
			JCExpression assign = maker.Assign(thisX, maker.Apply(List.<JCExpression>nil(), maker.Select(maker.Ident(((JCClassDecl) typeNode.get()).name), nameOfDefaultProvider), List.<JCExpression>nil()));
			assigns.append(maker.Exec(assign));
		}
		JCModifiers mods = maker.Modifiers(toJavacModifier(level), List.<JCAnnotation>nil());
		if (addConstructorProperties && !isLocalTypeNode(typeNode) && LombokOptionsFactory.getDelombokOptions(typeNode.getContext()).getFormatPreferences().generateConstructorProperties()) {
			addConstructorPropertiesFor(mods, typeNode, fieldsToParam);
		}
		if (onConstructor != null) mods.annotations = mods.annotations.appendList(copyAnnotations(onConstructor));
		return recursiveSetGeneratedBy(maker.MethodDef(mods, typeNode.toName("<init>"),
			null, List.<JCTypeParameter>nil(), params.toList(), List.<JCExpression>nil(),
			maker.Block(0L, nullChecks.appendList(assigns).toList()), null), source);
	}

	private List<JavacNode> fieldsNeedingBuilderDefaultsFor(JavacNode typeNode, List<JavacNode> fieldsToParam) {

		this.constructorTypeNode = typeNode;
		ListBuffer<JavacNode> out = new ListBuffer<JavacNode>();
		top:
		for (JavacNode node : typeNode.down()) {
			if (node.getKind() != Kind.FIELD) continue top;
			JCVariableDecl varDecl = (JCVariableDecl) node.get();
			if ((varDecl.mods.flags & Flags.STATIC) != 0) continue top;
			for (JavacNode ftp : fieldsToParam) if (node == ftp) continue top;
			if (JavacHandlerUtil.hasAnnotation(Builder.Default.class, node)) out.append(node);
		}
		return out.toList();
	}

	private List<JavacNode> fieldsNeedingExplicitDefaultsFor(JavacNode typeNode, List<JavacNode> fieldsToParam) {

		this.constructorTypeNode = typeNode;
		ListBuffer<JavacNode> out = new ListBuffer<JavacNode>();
		top:
		for (JavacNode node : typeNode.down()) {
			if (node.getKind() != Kind.FIELD) continue top;
			JCVariableDecl varDecl = (JCVariableDecl) node.get();
			if (varDecl.init != null) continue top;
			if ((varDecl.mods.flags & Flags.FINAL) == 0) continue top;
			if ((varDecl.mods.flags & Flags.STATIC) != 0) continue top;
			for (JavacNode ftp : fieldsToParam) if (node == ftp) continue top;
			if (JavacHandlerUtil.hasAnnotation(Builder.Default.class, node)) continue top;
			out.append(node);
		}
		return out.toList();
	}

	private JCExpression defaultExpressionFor(JavacTreeMaker maker, JCExpression type) {
		if (this.constructorTypeNode == null && type == null) return maker.Literal(CTC_BOT, null);

		if (type instanceof JCPrimitiveTypeTree) {
